CREATE OR REPLACE FUNCTION public.cellar_said(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce((select case when c.dug >= cellar_depth()
                               then ' Cellar under it: ' || metres(cellar_depth()) || ' m deep.'
                               else ' Cellar under it: ' || metres(c.dug) || ' m of ' || metres(cellar_depth())
                                    || ' m dug.' end
                     from cellar_tile c where c.world_id = p_world and c.x = p_x and c.y = p_y), '')
$function$
